import React, { useState, useEffect } from "react";

const ToTopButton = (props) => {
    const [showButton, setShowButton] = useState(false);

    useEffect(() => {
        const toggleVisible = () => {
            setShowButton(document.documentElement.scrollTop > 1000);
        };
        window.addEventListener('scroll', toggleVisible);
        return () => window.removeEventListener('scroll', toggleVisible);
    }, []);

    const scrollToTop = () => {
        window.scrollTo({
            top: 0,
            left: 0,
            behavior: "smooth",
        });
    };

    return(
        <>
            {showButton && <div><button className="floatingObj_totopbutton fa-solid fa-arrow-up" style={props.appStyle} onClick={scrollToTop}></button></div>}
        </>
    )
}

export default ToTopButton;